int process_ticket(struct ceph_auth_client *ac, struct ceph_crypto_key *secret, void **p, void *end) {
    int ret = -EINVAL;
    struct ceph_ticket *ticket;
    struct ceph_auth_ticket_handler *handler;
    void *ticket_end;
    int ticket_type;
    int version;

    if (!ac || !secret || !p || !*p || !end || *p > end) {
        goto out;
    }

    /* decode ticket type and version */
    if (*p + sizeof(__le32) > end) {
        goto out;
    }
    ticket_type = le32_to_cpu(*(__le32*)(*p));
    *p += sizeof(__le32);

    if (*p + sizeof(__le32) > end) {
        goto out;
    }
    version = le32_to_cpu(*(__le32*)(*p));
    *p += sizeof(__le32);

    handler = get_ticket_handler(ac, ticket_type);
    if (!handler) {
        goto out;
    }

    ticket = kmalloc(sizeof(*ticket), GFP_NOFS);
    if (!ticket) {
        goto out;
    }

    ticket->type = ticket_type;
    ticket->version = version;
    ticket->handler = handler;

    /* decode the ticket data */
    ticket_end = *p;
    if (ticket_end > end) {
        goto out_free;
    }

    if (handler->encrypted) {
        ret = ceph_decrypt_ticket(secret, ticket, *p, ticket_end);
        if (ret < 0) {
            goto out_free;
        }
    } else {
        ret = ceph_copy_ticket_data(ticket, *p, ticket_end);
        if (ret < 0) {
            goto out_free;
        }
    }

    /* update session key and validity */
    ret = update_session_key(ac, ticket);
    if (ret < 0) {
        goto out_free;
    }

    ret = update_validity(ac, ticket);
    if (ret < 0) {
        goto out_free;
    }

    handler->ticket_blob = ticket->blob;
    handler->ticket_valid_until = ticket->valid_until;

    ret = 0;

out_free:
    if (ret < 0) {
        kfree(ticket);
    }
out:
    return ret;
}

int ceph_auth_client_process_ticket(struct ceph_auth_client *ac,
                                    struct ceph_crypto_key *secret,
                                    void **p, void *end)
{
  int ret = -EINVAL;
  struct ceph_auth_ticket_handler *handler = NULL;
  void *ticket_data = NULL;
  size_t ticket_len = 0;
  struct ceph_crypto_key new_key;

  // Decode ticket type and version
  if (*p + sizeof(__le32) > end) {
    goto out;
  }
  uint32_t ticket_type = le32_to_cpu(*(__le32*)(*p));
  (*p) += sizeof(__le32);

  if (*p + sizeof(__le32) > end) {
    goto out;
  }
  uint32_t version = le32_to_cpu(*(__le32*)(*p));
  (*p) += sizeof(__le32);

  // Retrieve the appropriate ticket handler
  handler = ceph_get_auth_ticket_handler(ticket_type);
  if (!handler) {
    goto out;
  }

  // Read ticket data length
  if (*p + sizeof(__le32) > end) {
    goto out;
  }
  ticket_len = le32_to_cpu(*(__le32*)(*p));
  (*p) += sizeof(__le32);

  if (*p + ticket_len > end) {
    goto out;
  }
  ticket_data = *p;
  *p += ticket_len;

  // Allocate memory for the new session key
  if (ceph_crypto_key_alloc(&new_key, CEPH_CRYPTO_KEY_MAX_SIZE) < 0) {
    goto out;
  }

  // Decrypt ticket if needed
  if (version > 0) {
    ret = ceph_decrypt_ticket(&new_key, secret, ticket_data, ticket_len);
    if (ret < 0) {
      goto out;
    }
  } else {
    // Direct copy if not encrypted
    memcpy(new_key.key, ticket_data, new_key.length);
  }

  // Update session key and validity
  ceph_auth_client_set_session_key(ac, &new_key);
  ac->ticket_valid = true;

  // Update ticket blob and validity in the handler
  handler->ticket_blob = ticket_data;
  handler->ticket_blob_len = ticket_len;
  handler->valid = true;

  ret = 0;
out:
  if (ticket_data) {
    // No need to free ticket_data, it's part of the input buffer
  }
  if (new_key.key) {
    ceph_crypto_key_free(&new_key);
  }
  return ret;
}

int ceph_auth_client_process_ticket(struct ceph_auth_client *ac,
                                    struct ceph_crypto_key *secret,
                                    void **p, void *end) {
    int ret = -EINVAL;
    struct ceph_auth_ticket_handler *handler = NULL;
    void *ticket_data = NULL;
    size_t ticket_len = 0;

    // Decode the ticket type and structure version
    uint32_t ticket_type;
    uint32_t version;
    ceph_decode_dout(&ticket_type, p, end);
    ceph_decode_dout(&version, p, end);

    // Retrieve the appropriate ticket handler
    handler = ceph_auth_get_ticket_handler(ac, ticket_type);
    if (!handler) {
        goto out;
    }

    // Get the length of the ticket data
    ceph_decode_dout(&ticket_len, p, end);
    if (ticket_len > (size_t)((uintptr_t)end - (uintptr_t)*p)) {
        ret = -EINVAL;
        goto out;
    }

    ticket_data = *p;
    *p += ticket_len;

    // Decrypt the ticket data if needed
    if (handler->encrypted) {
        ret = ceph_crypto_decrypt(ticket_data, ticket_len,
                                  secret->data, secret->len,
                                  &ticket_data, &ticket_len);
        if (ret < 0) {
            goto out;
        }
    }

    // Update session key and validity from the ticket
    ret = handler->update_key_and_validity(ac, ticket_data, ticket_len);
    if (ret < 0) {
        goto out;
    }

    // Update the ticket blob and validity in the handler
    handler->blob = ticket_data;
    handler->blob_len = ticket_len;
    handler->valid = 1;

    ret = 0;

out:
    if (ret < 0) {
        ceph_buffer_put(ticket_data);
    }
    return ret;
}

int ceph_auth_client_process_ticket(struct ceph_auth_client *ac,
                                    struct ceph_crypto_key *secret,
                                    void **p, void *end) {
    int ret = -EINVAL;
    struct ceph_auth_ticket_handler *handler = NULL;
    void *ticket_data = NULL;
    size_t ticket_len = 0;
    struct ceph_auth_ticket *ticket = NULL;

    if (!ac || !secret || !p || !end || *p > end) {
        goto out;
    }

    /* decode ticket header */
    if (end - *p < sizeof(*ticket)) {
        goto out;
    }
    ticket = (struct ceph_auth_ticket *)(*p);
    *p += sizeof(*ticket);

    handler = ceph_auth_get_ticket_handler(ac, ticket->type);
    if (!handler) {
        goto out;
    }

    ticket_len = le32_to_cpu(ticket->len);
    if (end - *p < ticket_len) {
        goto out;
    }

    ticket_data = *p;
    *p += ticket_len;

    if (ticket->encrypted) {
        ret = ceph_decrypt_ticket(secret, ticket_data, ticket_len,
                                  &ticket->session_key, &ticket->session_key_len,
                                  &ticket->valid_from, &ticket->valid_until);
    } else {
        ticket->session_key = ticket_data;
        ticket->session_key_len = ticket_len;
        ticket->valid_from = le64_to_cpu(ticket->valid_from);
        ticket->valid_until = le64_to_cpu(ticket->valid_until);
        ret = 0;
    }

    if (ret < 0) {
        goto out;
    }

    handler->update_ticket_blob(handler, &ticket->session_key, ticket->session_key_len,
                                 ticket->valid_from, ticket->valid_until);

out:
    if (handler) {
        ceph_auth_put_ticket_handler(handler);
    }
    if (ticket_data && !ticket->encrypted) {
        kfree(ticket_data);
    }
    return ret;
}

int ceph_auth_client_process_ticket(struct ceph_auth_client *ac,
                                    struct ceph_crypto_key *secret,
                                    void **p, void *end) {
    int ret = -EINVAL;
    struct ceph_auth_ticket_handler *handler = NULL;
    void *ticket_data = NULL;
    size_t ticket_len = 0;
    struct ceph_crypto_key *new_key = NULL;

    // Decode the ticket type and version
    if ((ret = ceph_decode_auth_ticket_type(p, end, &handler)) < 0)
        goto out;

    if ((ret = ceph_decode_ticket_data(p, end, &ticket_data, &ticket_len)) < 0)
        goto out;

    // Decrypt the ticket if necessary
    if (handler->encrypted) {
        if (!secret) {
            ret = -ENOKEY;
            goto out;
        }
        if ((ret = ceph_decrypt_ticket(secret, ticket_data, ticket_len,
                                       &new_key)) < 0)
            goto out;
    } else {
        new_key = ceph_crypto_key_create();
        if (!new_key) {
            ret = -ENOMEM;
            goto out;
        }
        memcpy(new_key->key, ticket_data, ticket_len);
        new_key->key_len = ticket_len;
    }

    // Update session key and validity
    ac->session_key = new_key;
    if ((ret = ceph_update_validity(ac, handler, ticket_data, ticket_len)) < 0)
        goto out;

    // Update ticket blob and validity in handler
    handler->update_ticket_blob(handler, ac, ticket_data, ticket_len);
    handler->set_valid(handler, ac);

    ret = 0;

out:
    if (ticket_data)
        free(ticket_data);
    return ret;
}
